const approvedCanonVersion = 'canon-v1.0';
const approvedCanonRef = '977755913d9ad41e4f16392d01ea993507af4102';

const ordered = $input.all()
  .map((item, inputIndex) => ({ item, inputIndex }))
  .filter(({ item }) => item.json?.status === 'IDEA')
  .sort((a, b) => {
    const aRow = Number(a.item.json.row_number);
    const bRow = Number(b.item.json.row_number);
    const aHasRow = Number.isFinite(aRow);
    const bHasRow = Number.isFinite(bRow);
    if (aHasRow && bHasRow && aRow !== bRow) return aRow - bRow;
    if (aHasRow !== bHasRow) return aHasRow ? -1 : 1;
    const storyOrder = String(a.item.json.storyId ?? '').localeCompare(String(b.item.json.storyId ?? ''));
    return storyOrder || a.inputIndex - b.inputIndex;
  });

const classifyCandidate = ({ item, inputIndex }) => {
  const story = item.json;
  const marker = String(story.canonInitializationState ?? '').trim();
  const canonVersion = String(story.canonVersion ?? '').trim();
  const canonRef = String(story.canonRef ?? '').trim();
  const blankLineage = canonVersion === '' && canonRef === '';
  const exactExpectedLineage =
    canonVersion === approvedCanonVersion &&
    canonRef.toLowerCase() === approvedCanonRef.toLowerCase();

  let candidateSelectionOutcome = 'INTEGRITY_FAILURE';
  if (marker === '' && blankLineage) {
    candidateSelectionOutcome = 'PRE_CANON_LEGACY';
  } else if (
    (marker === 'PENDING' && (blankLineage || exactExpectedLineage)) ||
    (marker === 'ASSIGNED' && exactExpectedLineage) ||
    (marker === '' && exactExpectedLineage)
  ) {
    candidateSelectionOutcome = 'ELIGIBLE';
  }

  return { item, inputIndex, candidateSelectionOutcome };
};

const classified = ordered.map(classifyCandidate);
const selected =
  classified.find((candidate) => candidate.candidateSelectionOutcome === 'ELIGIBLE') ??
  classified.find((candidate) => candidate.candidateSelectionOutcome === 'INTEGRITY_FAILURE');

if (!selected) return [];

return [{
  json: {
    ...selected.item.json,
    candidateSelectionEligible: selected.candidateSelectionOutcome === 'ELIGIBLE',
    candidateSelectionOutcome: selected.candidateSelectionOutcome,
  },
  pairedItem: { item: selected.inputIndex },
}];

const story = $json;
const approvedCanonVersion = 'canon-v1.0';
const approvedCanonRef = '977755913d9ad41e4f16392d01ea993507af4102';
const releaseConfigValid = /^canon-v[0-9]+\.[0-9]+$/.test(approvedCanonVersion) && /^[0-9a-f]{40}$/i.test(approvedCanonRef);
const marker = String(story.canonInitializationState ?? '').trim();
const canonVersion = String(story.canonVersion ?? '').trim();
const canonRef = String(story.canonRef ?? '').trim();
const blankLineage = canonVersion === '' && canonRef === '';
const exactExpectedLineage = canonVersion === approvedCanonVersion && canonRef.toLowerCase() === approvedCanonRef.toLowerCase();
const existingFormatValid = /^canon-v[0-9]+\.[0-9]+$/.test(canonVersion) && /^[0-9a-f]{40}$/i.test(canonRef);
let canonInitializationValid = true;
let needsCanonWrite = false;
let canonInitializationAction = 'USE_EXISTING';
let errorCode = '';
let message = '';
if (!releaseConfigValid) {
  canonInitializationValid = false;
  errorCode = 'GOVERNED_CANON_RELEASE_INVALID';
  message = 'The explicitly governed approved canon release configuration is missing or invalid.';
} else if (marker === '' && blankLineage) {
  canonInitializationValid = false;
  errorCode = 'CANON_LINEAGE_INVALID';
  message = 'Blank marker plus blank canon lineage is PRE-CANON LEGACY under D-012 and is not eligible for automatic initialization.';
} else if (marker === 'PENDING' && blankLineage && story.status === 'IDEA') {
  needsCanonWrite = true;
  canonInitializationAction = 'ASSIGN';
} else if (marker === 'PENDING' && exactExpectedLineage && story.status === 'IDEA') {
  needsCanonWrite = true;
  canonInitializationAction = 'RECOVER_MARKER';
} else if (marker === 'ASSIGNED' && exactExpectedLineage) {
  canonInitializationAction = 'USE_EXISTING';
} else if (marker === '' && exactExpectedLineage) {
  canonInitializationAction = 'USE_EXISTING_LEGACY_MARKER';
} else {
  canonInitializationValid = false;
  errorCode = 'CANON_INITIALIZATION_INTEGRITY_FAILED';
  message = existingFormatValid ? 'Story canon lineage conflicts with its initialization marker or the currently governed approved release; existing canon was not overwritten.' : 'Story canon initialization marker/lineage state is malformed or incomplete; existing values were not overwritten.';
}
return { json: { ...story, canonVersion, canonRef, canonInitializationState: marker, approvedCanonVersion, approvedCanonRef, releaseConfigValid, exactExpectedLineage, canonInitializationValid, needsCanonWrite, canonInitializationAction, targetCanonVersion: canonInitializationAction === 'ASSIGN' ? approvedCanonVersion : canonVersion, targetCanonRef: canonInitializationAction === 'ASSIGN' ? approvedCanonRef : canonRef, errorCode, message } };

const story = $json;
const expected = $('Classify Canon Initialization').first().json;
const verified = story.storyId === expected.storyId && story.status === 'IDEA' && String(story.canonInitializationState ?? '').trim() === 'ASSIGNED' && String(story.canonVersion ?? '').trim() === expected.targetCanonVersion && String(story.canonRef ?? '').trim().toLowerCase() === String(expected.targetCanonRef ?? '').trim().toLowerCase();
return { json: { ...story, canonInitializationVerified: verified, errorCode: verified ? '' : 'CANON_INITIALIZATION_VERIFY_FAILED', message: verified ? '' : 'Persisted Story canon initialization could not be verified exactly; Concept Generation did not proceed.' } };

